// Golden parity tests for the gentle-notes card chrome: a faithful replica of
// gentle-shell's renderCard panel path (lib/shell-card.ts). The golden
// fixtures below were generated by running the REAL implementation (via the
// upstream clone) with this exact fake theme and card, so byte equality here
// proves visual parity with the Status/Todos rail cards.
import assert from "node:assert/strict";
import { afterEach, describe, it } from "node:test";
import {
	CARD_GLYPH,
	CARD_TONE,
	renderCardPanel,
	cardLine,
	cardBottom,
	cardTop,
	panelExtraRows,
	panelHeaderRow,
	panelInnerWidth,
	type PanelCard,
} from "../src/card-chrome.ts";

const STYLE_SLOT = Symbol.for("gentle-pi.card-style");
const previousStyle = (globalThis as Record<symbol, unknown>)[STYLE_SLOT];

afterEach(() => {
	if (previousStyle === undefined) delete (globalThis as Record<symbol, unknown>)[STYLE_SLOT];
	else (globalThis as Record<symbol, unknown>)[STYLE_SLOT] = previousStyle;
});

const theme = {
	fg: (role: string, text: string) => `<${role}>${text}</${role}>`,
	bg: (role: string, text: string) => `[bg:${role}]${text}\x1b[49m`,
};

const card: PanelCard = {
	title: "Notes",
	subtitle: "2 pend · 1 sent",
	body: [
		"<accent>✉</accent> revisar el padding del footer del blog <muted>➤</muted>",
		"<success>✓</success> <dim>~~mandar el PR~~</dim>",
	],
	tone: CARD_TONE.INFO,
	glyph: CARD_GLYPH,
};

describe("golden parity with gentle-shell renderCard (panel mode)", () => {
	it("matches the outlined neon frame byte for byte", () => {
		(globalThis as Record<symbol, unknown>)[STYLE_SLOT] = "neon";
		const lines = renderCardPanel(card, theme, 46, { hint: "alt+n", expanded: true });
		assert.deepEqual(lines, [
			"<border>╭</border><border>─ </border><accent>✎ Notes</accent> <muted>·</muted> <muted>2 pend · 1 sent</muted><border> ─────────</border> <dim>alt+n</dim> <border>╮</border>",
			"<border>│</border> <text><accent>✉</accent> revisar el paddi\u001b[0m…\u001b[0m <border>│</border>",
			"<border>│</border> <text>footer del blog <muted>➤</muted></t\u001b[0m…\u001b[0m <border>│</border>",
			"<border>│</border> <text><success>✓</success> <dim>~~mandar \u001b[0m…\u001b[0m <border>│</border>",
			"<border>│</border> <text>PR~~</dim></text>                    <border>│</border>",
			"<border>╰</border><border>────────────────────────────────────────────╯</border>",
		]);
		assert.equal(panelHeaderRow(theme, 46), 0);
		assert.equal(panelExtraRows(theme, 46), 0);
		assert.equal(panelInnerWidth(theme, 46), 42);
	});

	it("matches the painted float panel byte for byte", () => {
		(globalThis as Record<symbol, unknown>)[STYLE_SLOT] = "float";
		const lines = renderCardPanel(card, theme, 46, { hint: "alt+n", expanded: true });
		assert.deepEqual(lines, [
			" [bg:toolSuccessBg]<border>▎</border><border>                                           </border>\u001b[49m ",
			" [bg:toolSuccessBg]<border>▎</border> <accent>✎ Notes</accent>\u001b[0m[bg:toolSuccessBg]…\u001b[0m[bg:toolSuccessBg]\u001b[49m ",
			" [bg:toolSuccessBg]<border>▎</border><border>                                           </border>\u001b[49m ",
			" [bg:toolSuccessBg]<border>▎</border> <text><accent>✉</accent> revisar el pad\u001b[0m[bg:toolSuccessBg]…\u001b[0m[bg:toolSuccessBg] <border> </border>\u001b[49m ",
			" [bg:toolSuccessBg]<border>▎</border> <text>del footer del blog <muted>➤</mut\u001b[0m[bg:toolSuccessBg]…\u001b[0m[bg:toolSuccessBg] <border> </border>\u001b[49m ",
			" [bg:toolSuccessBg]<border>▎</border> <text><success>✓</success> <dim>~~manda\u001b[0m[bg:toolSuccessBg]…\u001b[0m[bg:toolSuccessBg] <border> </border>\u001b[49m ",
			" [bg:toolSuccessBg]<border>▎</border> <text>PR~~</dim></text>                  <border> </border>\u001b[49m ",
			" [bg:toolSuccessBg]<border>▎</border><border>                                           </border>\u001b[49m ",
		]);
		assert.equal(panelHeaderRow(theme, 46), 1);
		assert.equal(panelExtraRows(theme, 46), 2);
		assert.equal(panelInnerWidth(theme, 46), 40);
	});

	it("defaults to the float style when the shared slot is unset", () => {
		delete (globalThis as Record<symbol, unknown>)[STYLE_SLOT];
		assert.equal(panelInnerWidth(theme, 46), 40);
	});
});

describe("chrome fallbacks and narrow shapes", () => {
	it("keeps the outlined frame in float style when the theme has no background", () => {
		(globalThis as Record<symbol, unknown>)[STYLE_SLOT] = "float";
		const noBgTheme = { fg: theme.fg };
		const lines = renderCardPanel(card, noBgTheme, 46, { hint: "alt+n", expanded: true });
		assert.equal(panelHeaderRow(noBgTheme, 46), 0);
		assert.equal(panelInnerWidth(noBgTheme, 46), 42);
		assert.ok(lines[0]?.startsWith("<border>╭</border>"), "the outlined frame opens the card");
		assert.ok(lines[lines.length - 1]?.includes("╯"), "the outlined frame closes the card");
	});

	it("keeps the outlined frame below the float minimum width", () => {
		(globalThis as Record<symbol, unknown>)[STYLE_SLOT] = "float";
		assert.equal(panelInnerWidth(theme, 9), 5);
		assert.equal(panelHeaderRow(theme, 9), 0);
	});

	it("draws the degenerate one-column shapes", () => {
		(globalThis as Record<symbol, unknown>)[STYLE_SLOT] = "neon";
		assert.equal(cardTop(card, theme, 1), "<border>╭</border>");
		assert.equal(cardLine("x", CARD_TONE.INFO, theme, 1), "<border>│</border>");
		assert.equal(cardBottom(CARD_TONE.INFO, theme, 1), "<border>╰</border>");
	});

	it("returns no rows for nonpositive widths", () => {
		(globalThis as Record<symbol, unknown>)[STYLE_SLOT] = "neon";
		assert.deepEqual(renderCardPanel(card, theme, 0, { expanded: true }), []);
		assert.deepEqual(renderCardPanel(card, theme, -3, { expanded: true }), []);
	});
});
